"""Public payload types for Mantle hook insertion points."""

from __future__ import annotations

from typing import Any, Literal, Optional

from pydantic import BaseModel, ConfigDict, Field


class CallInfo(BaseModel):
    """Telephony / session identity, when present."""

    model_config = ConfigDict(frozen=True)

    phone_number: Optional[str] = None
    metadata: dict[str, Any] = Field(default_factory=dict)


class ChannelInfo(BaseModel):
    """Channel identity and front-end metadata."""

    model_config = ConfigDict(frozen=True)

    name: Optional[str] = None
    metadata: dict[str, Any] = Field(default_factory=dict)


class HookPayload(BaseModel):
    """Identity carried by every payload. Engine-owned fields are read-only."""

    model_config = ConfigDict(frozen=True)

    sender_id: str
    call: CallInfo = Field(default_factory=CallInfo)
    channel: ChannelInfo = Field(default_factory=ChannelInfo)


class TurnStartedPayload(HookPayload):
    turn_id: Optional[str] = None
    is_voice: bool = False


class TurnFinishedPayload(HookPayload):
    turn_id: Optional[str] = None
    status: Literal["completed", "cancelled", "error"]


class IncomingMessagePayload(HookPayload):
    text: str
    message_id: Optional[str] = None


class ModelRequestPayload(HookPayload):
    messages: list[dict[str, Any]]
    model_settings: dict[str, Any] = Field(default_factory=dict)
    tool_names: list[str] = Field(default_factory=list)
    iteration: int = 0


class ModelResponsePayload(HookPayload):
    text: Optional[str] = None
    tool_calls: list[dict[str, Any]] = Field(default_factory=list)
    latency_ms: Optional[float] = None


class ToolCallPayload(HookPayload):
    tool_name: str
    arguments: dict[str, Any]
    headers: dict[str, str] = Field(default_factory=dict)


class ToolResultPayload(HookPayload):
    tool_name: str
    arguments: dict[str, Any]
    value: Any
    is_error: bool = False


class KnowledgeQueryPayload(HookPayload):
    query: str


class KnowledgeResultsPayload(HookPayload):
    query: str
    passages: list[dict[str, Any]]


class OutgoingTextPayload(HookPayload):
    text: str
    is_voice: bool = False
